old='''        currentHeadline = "DESCRIBE PASS — stable Claude auth — execution proof starting"\n        currentBody = null\n        renderStatus()\n        startExecutionProof(origin)\n    }\n\n    private fun startExecutionProof(origin: String) {\n'''
new='''        currentHeadline = if (resumePending) "DESCRIBE PASS — stable Claude auth — resuming same provider run" else "DESCRIBE PASS — stable Claude auth — execution proof starting"\n        currentBody = null\n        renderStatus()\n        if (resumePending) resumeExecutionProof(origin) else startExecutionProof(origin)\n    }\n\n    private fun resumeExecutionProof(origin: String) {\n        if (!resumePending || !describePassed || executionStarted || proofStopped) return\n        val input = ExecutionInput(JOB_ID, PROOF_QUESTION, PROOF_HANDOFF, SelectedProvider.CLAUDE, null, false)\n        val job = runCatching { engine.buildJob(input) }.getOrElse { block("ANDROID_RESUME_JOB_REBUILD_FAILED"); return }\n        val persistedFingerprint = runLatch.getString(RUN_LATCH_FINGERPRINT_KEY, null)\n        if (persistedFingerprint != job.frozenFingerprint) { block("ANDROID_RUN_RESUME_FROZEN_FINGERPRINT_MISMATCH"); return }\n        proofJob = job\n        val channel = providerChannel ?: run { block("ANDROID_BRIDGE_CHANNEL_UNBOUND"); return }\n        val envelope = JSONObject()\n            .put("job_id", job.jobId)\n            .put("context_pack_id", job.contextPackId)\n            .put("frozen_fingerprint", job.frozenFingerprint)\n            .put("provider_family", job.providerFamily)\n            .put("external_research", false)\n            .put("canonical_rights", "NONE")\n            .put("state_mutation_mode", "NONE")\n        val outbound = JSONObject().put("channel", channel).put("type", "RESUME_JOB").put("bridge_run_id", BRIDGE_RUN_ID).put("envelope", envelope)\n        resumeAttempt += 1\n        runLatch.edit().putString(RUN_LATCH_STATE_KEY, RUN_STATE_IN_FLIGHT).putLong(RUN_LATCH_LAST_SEEN_AT_KEY, System.currentTimeMillis()).putInt(RUN_LATCH_RESUME_COUNT_KEY, resumeAttempt).putString(RUN_LATCH_PHASE_KEY, "RESUME_DISPATCH").apply()\n        resumePending = false; executionStarted = true\n        recordDiagnostic("RESUME_JOB", origin, "bridge_run_id=$BRIDGE_RUN_ID;resume_attempt=$resumeAttempt;resubmit=false")\n        currentHeadline = "RUN RESUME — observing existing Claude conversation"; currentBody = null; renderStatus()\n        if (bridge?.post(origin, outbound.toString()) != true) { block("ANDROID_RESUME_JOB_POST_FAILED"); return }\n        handler.postDelayed({ if (!ackPassed && !proofStopped) block("ANDROID_RESUME_ACK_TIMEOUT") }, ACK_TIMEOUT_MS)\n        handler.postDelayed({ if (!terminalReceived && !proofStopped) block("ANDROID_RESUME_TERMINAL_TIMEOUT") }, RESUME_TERMINAL_TIMEOUT_MS)\n    }\n\n    private fun startExecutionProof(origin: String) {\n'''
assert s.count(old)==1; s=s.replace(old,new)

