old='''    private fun armRunLatch() {\n        runLatchArmed = true\n        runLatch.edit()\n            .putString(RUN_LATCH_STATE_KEY, RUN_STATE_IN_FLIGHT)\n            .putLong(RUN_LATCH_STARTED_AT_KEY, System.currentTimeMillis())\n            .apply()\n    }\n'''
new='''    private fun armRunLatch(job: ExecutionJob) {\n        runLatchArmed = true\n        val now = System.currentTimeMillis()\n        runLatch.edit()\n            .putString(RUN_LATCH_STATE_KEY, RUN_STATE_IN_FLIGHT)\n            .putLong(RUN_LATCH_STARTED_AT_KEY, now)\n            .putLong(RUN_LATCH_LAST_SEEN_AT_KEY, now)\n            .putString(RUN_LATCH_BRIDGE_RUN_ID_KEY, BRIDGE_RUN_ID)\n            .putString(RUN_LATCH_JOB_ID_KEY, job.jobId)\n            .putString(RUN_LATCH_PROVIDER_KEY, "ANTHROPIC")\n            .putString(RUN_LATCH_FINGERPRINT_KEY, job.frozenFingerprint)\n            .putString(RUN_LATCH_PHASE_KEY, "EXECUTE_DISPATCH")\n            .putInt(RUN_LATCH_RESUME_COUNT_KEY, 0)\n            .apply()\n    }\n\n    private fun markRunProgress(phase: String) {\n        if (!::runLatch.isInitialized || !runLatchArmed) return\n        runLatch.edit().putLong(RUN_LATCH_LAST_SEEN_AT_KEY, System.currentTimeMillis()).putString(RUN_LATCH_PHASE_KEY, phase.take(160)).apply()\n    }\n\n    private fun markRunRecoverable(code: String) {\n        if (!::runLatch.isInitialized || !runLatchArmed) return\n        runLatch.edit().putString(RUN_LATCH_STATE_KEY, RUN_STATE_RECOVERABLE).putLong(RUN_LATCH_LAST_SEEN_AT_KEY, System.currentTimeMillis()).putString(RUN_LATCH_PHASE_KEY, "RECOVERABLE:" + sanitizeCode(code)).apply()\n    }\n\n    private fun isResumeEligibleBlock(code: String): Boolean =\n        code.startsWith("ANDROID_PROVIDER_FAILED:CLAUDE_PROMPT_SUBMISSION_NOT_ESTABLISHED") ||\n        code.startsWith("ANDROID_PROVIDER_FAILED:CLAUDE_USER_TURN_NOT_MATERIALIZED") ||\n        code.startsWith("ANDROID_PROVIDER_FAILED:CLAUDE_GENERATION_NOT_OBSERVED") ||\n        code.startsWith("ANDROID_PROVIDER_FAILED:CLAUDE_RESUME_") ||\n        code == "ANDROID_TERMINAL_TIMEOUT" || code == "ANDROID_RESUME_TERMINAL_TIMEOUT" || code == "ANDROID_RESUME_ACK_TIMEOUT" || code == "ANDROID_RESUME_JOB_POST_FAILED"\n'''
assert s.count(old)==1; s=s.replace(old,new)

