s=s.replace('const val RUN_LATCH_TTL_MS = 300_000L','''const val RUN_LATCH_TTL_MS = 300_000L\n        const val MAX_RESUME_ATTEMPTS = 2\n        const val RESUME_TERMINAL_TIMEOUT_MS = 160_000L''')
