# Claude RESUME_JOB is observer-only: never writes to the composer and never clicks Send.
provider=root/'app/src/main/assets/nexus/claude_provider_c002.js'; j=provider.read_text()
anchor='''  async function executeJob(bridgeRunId,envelope){\n'''
resume='''  async function resumeJob(bridgeRunId,envelope){\n    if(running) throw new Error('CLAUDE_PROVIDER_ALREADY_RUNNING');\n    running=true;\n    try{\n      const auth=detectAuth();\n      if(auth.state!=='AUTHENTICATED') throw new Error('CLAUDE_NOT_AUTHENTICATED:'+auth.state);\n      if(envelope.provider_family!=='ANTHROPIC'||envelope.external_research!==false) throw new Error('CLAUDE_RESUME_ENVELOPE_INVALID');\n      await progress(bridgeRunId,'CLAUDE_RESUME_OBSERVER_STARTED');\n      await progress(bridgeRunId,'CLAUDE_RESUME_SNAPSHOT__'+compactTurnDiag(turnGenerationSnapshot(envelope)));\n      const result=await waitForStableJson(bridgeRunId,envelope,150000);\n      await progress(bridgeRunId,'CLAUDE_RESUME_RESPONSE_CAPTURED');\n      await nativeSend({channel:CHANNEL,type:'PROVIDER_RESULT',bridge_run_id:bridgeRunId,ok:true,result_pack:result.parsed,provider_meta:{ui_origin:location.origin,auth_observation:auth,exact_backend_model_exposed:false,completion_rule:'RESUME_EXISTING_CONVERSATION__COMPLETE_JSON_STABLE_8000MS',json_stable_ms:result.json_stable_ms,candidate_count:result.candidate_count,resumed:true}});\n    }catch(err){\n      const code=String(err?.message||err);\n      try{await nativeSend({channel:CHANNEL,type:'PROVIDER_RESULT',bridge_run_id:bridgeRunId,ok:false,error:'CLAUDE_RESUME_'+code});}catch(_){}\n    }finally{ running=false; setTimeout(publishStatus,2000); }\n  }\n\n  async function executeJob(bridgeRunId,envelope){\n'''
assert j.count(anchor)==1; j=j.replace(anchor,resume)
old='''    if(msg.type!=='EXECUTE_JOB') return;\n    if(running){\n      sendResponse({ok:false,error:'CLAUDE_PROVIDER_ALREADY_RUNNING'});\n      return;\n    }\n    sendResponse({ok:true,accepted:true});\n    setTimeout(()=>executeJob(msg.bridge_run_id,msg.envelope),0);\n    return;\n'''
new='''    if(msg.type!=='EXECUTE_JOB' && msg.type!=='RESUME_JOB') return;\n    if(running){ sendResponse({ok:false,error:'CLAUDE_PROVIDER_ALREADY_RUNNING'}); return; }\n    const resumed=msg.type==='RESUME_JOB';\n    sendResponse({ok:true,accepted:true,resumed});\n    setTimeout(()=>resumed?resumeJob(msg.bridge_run_id,msg.envelope):executeJob(msg.bridge_run_id,msg.envelope),0);\n    return;\n'''
assert j.count(old)==1; provider.write_text(j.replace(old,new))
